S = "shure-chargers"
# Shure chargers' command strings (see the spec's sources): < GET ... >, < SET ... >, answered < REP ... >.
text(S, "get_model", {}, "< GET MODEL >", device_reply="< REP MODEL {SBC220                          } >", expect_result={'ok': {'kind': 'value', 'value': 'SBC220'}})
telemetry(S, "model", inbound="< REP MODEL {SBC220                          } >", expect_state={'device': {'model': 'SBC220'}})
text(S, "get_firmware", {}, "< GET FW_VER >", device_reply="< REP FW_VER {2.0.15.2                } >", expect_result={'ok': {'kind': 'value', 'value': '2.0.15.2'}})
telemetry(S, "firmware", inbound="< REP FW_VER {2.0.15.2                } >", expect_state={'device': {'firmware': '2.0.15.2'}})
text(S, "get_device_id", {}, "< GET DEVICE_ID >", device_reply="< REP DEVICE_ID {Rack 1                         } >", expect_result={'ok': {'kind': 'value', 'value': 'Rack 1'}}, model="sbc220")
telemetry(S, "device_id", inbound="< REP DEVICE_ID {Rack 1                         } >", expect_state={'device': {'device_id': 'Rack 1'}}, model="sbc220")
text(S, "set_device_id", {'value': 'Lectern'}, "< SET DEVICE_ID {Lectern} >", device_reply="< REP DEVICE_ID {Lectern} >", expect_result={'ok': {'kind': 'ack'}}, model="sbc220")
text(S, "get_device_id_dock", {}, "< GET DEVICE_ID >", device_reply="< REP DEVICE_ID {DOCK0001} >", expect_result={'ok': {'kind': 'value', 'value': 'DOCK0001'}}, model="sbc850")
text(S, "flash", {'enabled': True}, "< SET FLASH ON >", device_reply="< REP FLASH ON >", expect_result={'ok': {'kind': 'ack'}})
text(S, "get_flash", {}, "< GET FLASH >", device_reply="< REP FLASH OFF >", expect_result={'ok': {'kind': 'value', 'value': 'OFF'}}, model="mxcwncs")
telemetry(S, "flash", inbound="< REP FLASH ON >", expect_state={'device': {'flash': True}})
text(S, "get_storage_mode", {}, "< GET STORAGE_MODE >", device_reply="< REP STORAGE_MODE ON >", expect_result={'ok': {'kind': 'value', 'value': 'ON'}}, model="sbc220")
telemetry(S, "storage_mode", inbound="< REP STORAGE_MODE OFF >", expect_state={'device': {'storage_mode': False}}, model="sbc220")
text(S, "set_storage_mode", {'enabled': True}, "< SET STORAGE_MODE ON >", device_reply="< REP STORAGE_MODE ON >", expect_result={'ok': {'kind': 'ack'}}, model="sbc220")
text(S, "toggle_storage_mode", {}, "< SET STORAGE_MODE TOGGLE >", device_reply="< REP STORAGE_MODE OFF >", expect_result={'ok': {'kind': 'ack'}}, model="sbc220")
text(S, "get_network", {}, "< GET NET_SETTINGS SC >", device_reply="< REP NET_SETTINGS SC MANUAL 192.168.001.025 255.255.255.000 000.000.000.000 00:0E:DD:45:60:EB >", expect_result={'ok': {'kind': 'value', 'value': 'MANUAL 192.168.001.025 255.255.255.000 000.000.000.000 00:0E:DD:45:60:EB'}})
text(S, "set_network", {'address': '192.168.1.25', 'netmask': '255.255.255.0', 'gateway': '0.0.0.0'}, "< SET NET_SETTINGS SC MANUAL 192.168.1.25 255.255.255.0 0.0.0.0 >", expect_result={'ok': {'kind': 'unverified'}})
text(S, "set_network_auto", {}, "< SET NET_SETTINGS SC AUTO na na na >", expect_result={'ok': {'kind': 'unverified'}})
telemetry(S, "network", inbound="< REP NET_SETTINGS SC MANUAL 192.168.001.025 255.255.255.000 000.000.000.000 00:0E:DD:45:60:EB >", expect_state={'network': {'mode': 'MANUAL', 'address': '192.168.001.025', 'netmask': '255.255.255.000', 'gateway': '000.000.000.000', 'mac': '00:0E:DD:45:60:EB'}})
text(S, "reboot", {}, "< SET REBOOT >", expect_result={'ok': {'kind': 'unverified'}})
text(S, "get_all", {'bay': 0}, "< GET 0 ALL >", expect_result={'ok': {'kind': 'unverified'}})
text(S, "get_module_type", {'module': 1}, "< GET 1 BATT_MODULE_TYPE >", device_reply="< REP 1 BATT_MODULE_TYPE 129 >", expect_result={'ok': {'kind': 'value', 'value': '129'}}, model="sbc220")
